from collections import defaultdict
class Solution:
    def destroyTargets(self, nums: List[int], space: int) -> int:
        cnt = defaultdict(int)
        mn = {}
        for x in nums:
            r = x % space
            cnt[r] += 1
            mn[r] = min(mn.get(r, float('inf')), x)
        best = max(cnt.values())
        return min(mn[r] for r in cnt if cnt[r] == best)

