class Solution {
public:
    int destroyTargets(vector<int>& nums, int space) {
        unordered_map<int,int> cnt;
        unordered_map<int,long long> mn;
        for (int x : nums) {
            int r = x % space;
            cnt[r]++;
            if (!mn.count(r) || x < mn[r]) mn[r] = x;
        }
        int best = 0;
        for (auto& [r, c] : cnt) best = max(best, c);
        long long ans = LLONG_MAX;
        for (auto& [r, c] : cnt)
            if (c == best) ans = min(ans, mn[r]);
        return (int)ans;
    }
};

