class Solution {
    public int destroyTargets(int[] nums, int space) {
        Map<Integer,Integer> cnt = new HashMap<>();
        Map<Integer,Integer> mn = new HashMap<>();
        for (int x : nums) {
            int r = x % space;
            cnt.merge(r, 1, Integer::sum);
            mn.merge(r, x, Math::min);
        }
        int best = 0;
        for (int c : cnt.values()) best = Math.max(best, c);
        int ans = Integer.MAX_VALUE;
        for (Map.Entry<Integer,Integer> e : cnt.entrySet())
            if (e.getValue() == best) ans = Math.min(ans, mn.get(e.getKey()));
        return ans;
    }
}

