var destroyTargets = function(nums, space) {
    const cnt = new Map(), mn = new Map();
    for (const x of nums) {
        const r = x % space;
        cnt.set(r, (cnt.get(r) || 0) + 1);
        mn.set(r, Math.min(mn.get(r) ?? Infinity, x));
    }
    const best = Math.max(...cnt.values());
    let ans = Infinity;
    for (const [r, c] of cnt) if (c === best) ans = Math.min(ans, mn.get(r));
    return ans;
};

