class Solution:
    def destroyTargets(self, nums: List[int], space: int) -> int:
        s = sorted(nums, key=lambda x: (x % space, x))
        best_cnt, best_val = 0, s[0]
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] % space == s[i] % space:
                j += 1
            if j - i > best_cnt:
                best_cnt, best_val = j - i, s[i]
            i = j
        return best_val

