class Solution {
public:
    int destroyTargets(vector<int>& nums, int space) {
        vector<int> s = nums;
        sort(s.begin(), s.end(), [&](int a, int b) {
            int ra = a % space, rb = b % space;
            return ra != rb ? ra < rb : a < b;
        });
        int bestCnt = 0, bestVal = s[0], i = 0;
        while (i < (int)s.size()) {
            int j = i;
            while (j < (int)s.size() && s[j] % space == s[i] % space) j++;
            if (j - i > bestCnt) { bestCnt = j - i; bestVal = s[i]; }
            i = j;
        }
        return bestVal;
    }
};

