class Solution {
    public int destroyTargets(int[] nums, int space) {
        Integer[] s = Arrays.stream(nums).boxed().toArray(Integer[]::new);
        Arrays.sort(s, (a, b) -> {
            int ra = a % space, rb = b % space;
            return ra != rb ? ra - rb : a - b;
        });
        int bestCnt = 0, bestVal = s[0], i = 0;
        while (i < s.length) {
            int j = i;
            while (j < s.length && s[j] % space == s[i] % space) j++;
            if (j - i > bestCnt) { bestCnt = j - i; bestVal = s[i]; }
            i = j;
        }
        return bestVal;
    }
}

